            "애드빌은 이부프로펜 성분의 진통제예요. 감기로 인한 발열과 두통, 치통, 생리통, 근육통, 신경통, 요통처럼 일상에서 자주 겪는 통증에 두루 써요. 관절 쪽으로는 골관절염이나 류마티양 관절염, 강직성 척추염 같은 질환의 통증에도 쓰이고요. 적응 범위가 넓은 편이죠.\n\n리퀵겔(연질캡슐)은 약물이 액상으로 담겨 있어요. 그래서 딱딱한 정제보다 몸에 퍼지는 흐름이 빠른 편이에요. 다만 \"몇 분 만에 듣는다\"는 식의 정해진 숫자는 식약처 허가사항에 나와 있지 않아요. 통증이 얼마나 센지, 속이 얼마나 비었는지에 따라 반응이 갈려요.\n\n효과가 약하게 느껴져도 임의로 양을 늘리기보다 정해진 용법 범위부터 확인하는 흐름이 안전해요.",
