            "1일 총 5정(1250mg)을 넘기지 않는 게 허가사항상 기본 한도예요. 다만 증상마다 용량이 달라요. 관절염 계열(류마티양 관절염·골관절염·강직성 척추염)은 성인 1회 1~2정(250~500mg)을 1일 2회, 12시간마다 먹어요.\n\n삠·타박상·수술 후·발치 후 통증, 생리통, 건염에는 처음에 2정(500mg)을 먹고 6~8시간 간격으로 1정(250mg)씩 이어가요. 편두통은 처음 3정(750mg)을 먹고, 30분 뒤부터 필요하면 1~2정(250~500mg)을 더할 수 있어요.\n\n급성통풍은 초회 3정(750mg) 뒤 발작이 가라앉을 때까지 8시간 간격으로 1정(250mg)씩 써요. 어떤 경우든 하루 5정을 넘기지 않아요.",
