          "복용 후 나타날 수 있는 흔한 부작용은 발진, 발적, 구역, 구토, 변비, 식욕부진, 어지러움이에요. 식약처 자료에 실린 목록이죠. 이런 증상이 나타나면 계속 먹지 말고 상태부터 지켜봐야 해요.\n\n바로 복용을 멈추고 병원을 찾아야 하는 신호도 정해져 있어요. 두드러기와 함께 후두·눈꺼풀·입술이 붓거나, 안색이 창백해지고 손발이 차가워지며 식은땀과 숨가쁨이 함께 나타나면 응급 신호예요. 고열과 함께 발진이나 물집이 전신 피부와 입·눈 점막에 번지는 경우, 천식 증상, 고정된 자리에 반복되는 발진, 고음이온차 대사성 산증(HAGMA)도 허가사항이 즉시 중단 대상으로 못 박은 증상들이에요.\n\n운전이나 기계 조작을 하는 사람이라면 졸음이 나타나는 경우가 있다는 점도 품목번호 202200658 허가사항에 담겨 있으니 참고해두면 좋아요.",
