            "10캡슐에 3,000원, 자체 수집 기준가로 보면 1캡슐당 300원 선이에요. 같은 이부프로펜 400mg 성분 안에서 비교하면 프리엔 10캡슐이 1캡슐당 150원, 이지앤6애니와 굿스펜이 각각 1캡슐당 180원으로 훨씬 낮은 편이죠.\n\n성분과 함량이 같은 이부프로펜 400mg군 안에서 보면 탁센400이 가격대 상단에 있는 셈이에요. 연질캡슐 제형이라 흡수가 빠르다는 점을 장점으로 보는 분들도 있지만, 성분 자체의 효과 차이는 크지 않아요. 가격은 수시로 바뀔 수 있어요.\n\n하루 8캡슐까지 먹는 경우와 하루 2~3캡슐만 먹는 경우는 한 달 비용 차이가 꽤 벌어질 수 있어요. 예산을 아끼고 싶다면 같은 성분의 정제 제품을 함께 놓고 비교해보는 것도 방법이고요. 정확한 현재가는 아래 버튼에서 확인하는 게 가장 빨라요.",
