            "부작용은 위장관 쪽을 가장 조심해야 해요. 위부 불쾌감, 위통, 구역, 소화불량, 속쓰림, 설사나 변비가 비교적 흔하게 나타날 수 있어요. 드물게는 위장출혈, 소화성궤양, 천공처럼 심각한 위장 이상반응도 보고돼요.\n\n심혈관계도 주의가 필요해요. 식약처 등록 정보엔 심근경색, 뇌졸중 같은 중대한 혈전 반응 위험이 커질 수 있다고 나와요. 이 밖에 졸음, 어지러움, 두통, 이명, 부종이 생기기도 하고, 아주 드물게 두드러기·발진 같은 과민반응이나 호흡곤란이 올 수 있어요. 이런 증상이 보이면 복용을 멈추고 의사나 약사와 상의하세요. 아주 드물게는 백혈구감소나 혈소판감소 같은 혈액 이상이 나타나기도 하니 장기 복용 시 참고하세요. 이 부작용 목록은 식약처 허가사항에 등록된 내용이에요.",
