            "생약이라도 부작용이 아예 없는 건 아니에요. 식약처 등록 정보에는 감초가 많거나 오래 들어가면 소변량이 줄고 얼굴·손발이 붓거나 혈압이 오르고 두통이 생기는 위알도스테론증이 나타날 수 있다고 적혀 있어요. 이때 저칼륨혈증이 함께 오면 무력감, 팔다리 경련, 마비 같은 근육 증상으로 이어지기도 해요.\n\n마황 성분 탓에 불면, 땀 과다, 가슴 두근거림, 소변이 잦아지는 증상이 생기기도 하죠. 위장이 약하면 식욕부진·속 불편·구역·구토·설사가 올 수 있고요. 드물게 피곤함·황달·진한 소변처럼 간 이상을 의심할 증상이 보고된 적도 있다고 식약처는 안내해요. 즉시 중단하세요. 이런 신호가 보이면 바로 복용을 멈추고 의사·약사와 상의하세요. 보관도 중요해요. 직사광선을 피하고 습기가 적은 서늘한 곳에, 어린이 손이 닿지 않게 원래 용기 그대로 밀폐 보관하라고 허가사항에 명시돼 있어요.",
