            "프리엔에프는 류마티양 관절염과 골관절염(퇴행성 관절질환), 강직성 척추염, 건염(힘줄염) 같은 관절·근골격계 통증에 쓰는 약이에요. 급성 통풍 발작이나 월경곤란증, 활액낭염, 염좌나 좌상 같은 외상성 통증에도 허가된 적응증이에요. 수술 후 통증, 편두통, 발치(이를 뽑은) 후 통증까지 두루 적용돼요. 전부 식약처 허가사항에 등록된 적응증이에요.\n\n적응증이 이렇게 여러 갈래인 이유가 있어요. 나프록센이 염증과 통증을 함께 잡는 소염진통 기전이라서예요. 단순 두통약과는 달라요. 관절 부기나 근골격 염증처럼 염증이 동반된 통증에 상대적으로 잘 맞는 편이에요. 다만 이 약은 원인 치료제가 아니에요. 증상을 가라앉히는 대증요법이에요. 통증이 반복되거나 오래가면 원인을 찾는 진료부터 받아야 해요.",
