            "코비메타비정 복용법은 간단해요. 식약처 허가사항에 그대로 나와 있어요. 만 12세 이상 청소년과 성인 기준으로 하루 한 번, 한 정을 물과 함께 삼키면 돼요. 정해진 용량보다 많이 먹는다고 효과가 더 좋아지는 약이 아니라서 용법을 지키는 게 중요해요.\n\n한 달 정도 꾸준히 먹었는데도 신경통이나 근육통 같은 증상이 나아지지 않으면 바로 복용을 멈추고 의사나 약사와 상의하는 게 맞아요. 어린이가 먹을 땐 보호자가 용량을 확인해줘야 하고요. 녹차나 홍차처럼 탄닌이 든 차와 함께 먹으면 흡수에 영향을 줄 수 있어 시간 간격을 두는 게 좋아요. 제산제나 먹는 테트라사이클린 계열 항생제, 레보도파를 복용 중이면 함께 먹지 않아야 해요.\n\n혹시 하루 깜빡하고 못 먹었더라도, 다음 날 두 정을 몰아 먹는 방식은 권하지 않아요. 정해진 하루 한 정 리듬을 유지하는 편이 흡수와 안전 면에서 더 나아요.",
