            "만 12세 이상 소아와 성인은 1회 1~2정씩, 1일 3~4회 먹어요. 복용 간격은 4~6시간을 두고, 통증이나 열이 있을 때 필요시 먹는 방식이에요. 정해진 시간마다 무조건 먹는 약은 아니에요.\n\n제일 중요한 선은 하루 최대량이에요. 아세트아미노펜으로 하루 4g, 즉 8정을 넘기면 안 돼요. 이 선은 꼭 지켜요. 이 한도를 넘으면 간에 부담이 갈 수 있거든요. 가능한 한 최단기간, 최소 유효용량으로 먹는 게 원칙이에요.\n\n스스로 판단해 오래 먹는 것도 피해야 해요. 통증이면 성인은 10일, 소아는 5일 이상, 발열이면 3일 이상 이어서 복용하지 않아요. 그런데도 증상이 계속되거나 심해지면, 그때는 의사나 약사와 상의하는 게 맞아요. 식약처 허가사항 기준이에요.",
